fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    // Since the array is sorted non-decreasingly, all duplicates appear consecutively.
    // We just count how many times a value changes as we iterate.
    let mut unique_count = 1; // first element is always unique
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            unique_count += 1;
        }
    }

    unique_count
}